function renderRadar(){const region=localStorage.getItem('nebo-region'),f=state.geo?.features.find(x=>regionName(x)===region),center=state.userPos?[state.userPos.lat,state.userPos.lon]:(f?centerOf(f):[49,31]);$('#radarRegion').textContent=(region||'Україна')+(state.userPos?' · GPS':'');radarUI.setBorders(state.geo,state.snapshot.alerts);radarUI.setAlertFills(state.raionFillItems);const guardKm=state.guard.enabled&&state.userPos?state.guard.radius:null;let _minD=null;for(const _e of flowEvents()){if(_e.lat==null||_e.lon==null)continue;const _d=distKm(center[0],center[1],_e.lat,_e.lon);if(_minD==null||_d<_minD)_minD=_d}if(!state.radarRangeManual&&_minD!=null){const _fit=_minD<=50?50:_minD<=100?100:_minD<=200?200:_minD<=400?400:_minD<=800?800:1500;if(_fit!==state.radarRange){state.radarRange=_fit;try{localStorage.setItem('nebo-radar-range',String(_fit))}catch(e){}const _rb=document.querySelector('#radarRange');if(_rb)_rb.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',Number(x.dataset.range)===_fit))}}scopeUI.update(flowEvents(),center,{range:state.radarRange,guardKm:guardKm,pin:state.radarPin,geo:state.geo,raionFills:state.raionFillItems,alertRegions:state.snapshot.alerts.map(a=>a.region),geoSig:(state.geo?state.geo.features.length:0)+':'+[...new Set(state.snapshot.alerts.map(a=>a.region))].sort().join('|')+':'+((state.raionFillItems||[]).map(i=>i.name).join(','))});if(state.radarMode==='map'){radarUI.render(flowEvents(),center,{guardKm:guardKm});radarUI.setSatellite(state.satelliteOn);radarUI.renderUser(state.userPos);}const c=countCats(state.snapshot.events),near=nearestEvent(),metrics=[['БПЛА',c.uav],['Ракетні',c.missile+c.ballistic],['КАБ',c.kab],['Усього повідомлень',state.snapshot.events.length]];if(near&&near._distKm!=null)metrics.push(['Найближча',fmtDist(near._distKm)]);$('#radarSummary').innerHTML=metrics.map(([n,v])=>`<div class="metric"><b>${v}</b><span>${n}</span></div>`).join('')}
function renderTimeline(){const items=state.timeline.slice(0,12);$('#timeline').innerHTML=items.length?items.map(x=>`<div class="timeline-item"><time>${clock(x.at,true)}</time><i></i><p>${esc(x.text)}<br><small>${esc(x.source)}</small></p></div>`).join(''):'<div class="empty">Зміни з’являться після наступного реального оновлення.</div>'}
function renderRail(){const ten=state.timeline.filter(x=>Date.now()-x.at<10*60000),n=ten.filter(x=>x.text.startsWith('Нове')).length,end=ten.filter(x=>x.text.includes('більше не')).length;$('#railChanges').innerHTML=`<p><b>+${n}</b> нових monitoring повідомлень</p><p><b>−${end}</b> подій більше не активні</p>`}
function renderHistory(){const max=Math.max(1,...state.history.map(x=>x.events));$('#historyScale').innerHTML=state.history.map(x=>`<div class="history-bar" style="height:${18+Math.round(x.events/max*52)}px" title="${x.events} повідомлень"><span>${clock(x.at,true)}</span></div>`).join('')}
function openDetail(e){if(!e)return;const d=$('#detailSheet');if(e.official){$('#detailContent').innerHTML=`<span class="detail-type">ОФІЦІЙНИЙ СТАТУС</span><h2 class="detail-title">${e.status==='active'?'Повітряна тривога':'Поточний статус'}</h2><p>${e.status==='active'?'Активний офіційний сигнал тривоги.':'Активний сигнал повітряної тривоги не зафіксований у поточних даних.'}</p><div class="explain-box">Регіон: ${esc(e.region)}<br>Джерело: ${esc(e.source)}<br>Monitoring не скасовує офіційний сигнал.${e.status==='active'?(e.partial&&e.raions&&e.raions.length?'<br>Сигнал лише в районах: '+e.raions.map(esc).join(', '):'<br>Сигнал по всій області.') : ''}</div><button class="text-button" id="makeMyRegion">Зробити моїм регіоном</button>`}else{const m=META[e.category]||META.other,srcs=[...new Set((e.correlated||[e]).map(x=>x.source))];$('#detailContent').innerHTML=`<span class="detail-type">${e.advisory?'ІНФОРМАЦІЙНЕ MONITORING ПОВІДОМЛЕННЯ':'MONITORING ПОВІДОМЛЕННЯ'}</span><h2 class="detail-title">${esc(e.kind==='shahed'&&!/shahed|шахед/i.test(e.subtype||'')?'Шахед · '+(e.subtype||m.label):(e.subtype||m.label))}</h2><div class="detail-grid">${field('Останнє оновлення',clock(e.timestamp))}${field('Свіжість',fresh(e.timestamp))}${field('Місце',e.region||e.derivedRegion||e.settlement||'Не вказано')}${field('Позиція',e.areaOnly?'Тільки область':positionLabel(e.positionQuality))}${e.speed!=null?field('Швидкість',Math.round(e.speed)+' км/год'):''}${field('Напрямок',e.heading!=null?`${Math.round(e.heading)}° · ${compass(e.heading)}`:'Не передано')}${state.userPos&&e._distKm!=null?field('Відстань до вас',fmtDist(e._distKm)+(e._closing&&e._etaMin!=null?` · підліт ${fmtEta(e._etaMin)}`:e._closing?' · наближається':'')):''}${field('Невизначеність',e.uncertaintyKm!=null?`±${e.uncertaintyKm} км`:'Не передано')}${field('Оцінка джерела',e.confidence?.toUpperCase()||'Не передано')}${field('Агрегованих повідомлень',e.sourceCount??'Не передано')}${field('Напрямок за даними source',e.destination||'Не передано')}${field('Схожі повідомлення',srcs.length>1?`${srcs.length} джерела`:'Не знайдено')}${e.fusedCount>1?field('Зведено в контакт',`${e.fusedCount} повідомлень у радіусі 18 км`):''}</div><h3>Джерела</h3><p>${srcs.map(esc).join(' · ')}</p><div class="explain-box"><b>Чому це показано?</b><br>Тип: ${esc(m.label)}. Статус: monitoring. Подію отримано безпосередньо з ${esc(e.source)}. ${e.areaOnly?'Точкова позиція не показується, бо джерело передало лише область.':`Якість позиції: ${esc(positionLabel(e.positionQuality))}.`} ${srcs.length>1?'Знайдено схоже повідомлення в іншому джерелі; це не доводить, що йдеться про той самий фізичний об’єкт.':''}</div><p class="micro">Координати, напрямок та інші monitoring дані можуть бути приблизними. НЕБО UA не прогнозує майбутній маршрут чи ціль.</p>`}d.showModal();const mr=$('#makeMyRegion');if(mr)mr.onclick=()=>{if(e.region)setRegion(e.region);d.close()}}
function renderQuiet(region,alerts,events){$('#quietClock').textContent=clock(new Date(),false);$('#quietRegion').textContent=region||'Регіон не обрано';$('#quietOfficial').innerHTML=`<div class="quiet-status">${alerts.length?'🔴 ПОВІТРЯНА ТРИВОГА':'Офіційний сигнал не зафіксований у поточних даних'}</div>`;$('#quietMonitoring').innerHTML=`<div class="quiet-monitor">Monitoring повідомлень: ${events.length}</div>`;$('#quietUpdated').textContent=state.lastSuccess?'Оновлено '+clock(state.lastSuccess):'Немає оновлення'}
function setup(){document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav)showView(nav.dataset.nav)});$('#layerButton').onclick=()=>{const p=$('#layerPanel');p.hidden=!p.hidden;$('#layerButton').setAttribute('aria-expanded',String(!p.hidden))};$('#refreshButton').onclick=load;$('#regionSelect').onchange=e=>{const f=state.geo?.features[Number(e.target.value)];setRegion(f?regionName(f):'')};$('#locateButton').onclick=locate;const hb=$('#homeButton');if(hb)hb.onclick=()=>mapUI.showHome(localStorage.getItem('nebo-region')||'');const gb=$('#gpsButton');if(gb)gb.onclick=()=>locateAndCenter();$('#quietButton').onclick=()=>{$('#quietScreen').hidden=false;renderSky()};$('#exitQuiet').onclick=()=>$('#quietScreen').hidden=true;$('#settingsButton').onclick=()=>{$('#settingsDialog').showModal();renderAudioSettings()};$$('.sheet-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#autoRefresh').checked=localStorage.getItem('nebo-auto')!=='false';$('#autoRefresh').onchange=e=>localStorage.setItem('nebo-auto',e.target.checked);$('#reduceMotion').checked=localStorage.getItem('nebo-motion')==='reduce';$('#reduceMotion').onchange=e=>{localStorage.setItem('nebo-motion',e.target.checked?'reduce':'normal');document.body.classList.toggle('reduce-motion',e.target.checked)};document.body.classList.toggle('reduce-motion',$('#reduceMotion').checked);setupAudioSettings();mountAdSlots();setupOverlays();setupGuard();setupRadarSearch();setupScope();$('#startButton').onclick=()=>{localStorage.setItem('nebo-onboarded','1');$('#onboarding').close();showView('skyView')};if(!localStorage.getItem('nebo-onboarded'))$('#onboarding').showModal();addEventListener('online',load);addEventListener('offline',renderGlobal);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&$('#autoRefresh').checked&&Date.now()-(state.lastSuccess?.getTime()||0)>30000)load()});addEventListener('nebo:position',e=>{if(e.detail&&Number.isFinite(e.detail.latitude))applyPosition(e.detail)});setInterval(()=>{renderGlobal();renderSky();const hasActive=state.snapshot.events.length>0;const interval=hasActive?7000:30000;if($('#autoRefresh').checked&&Date.now()-(state.lastSuccess?.getTime()||0)>interval)load()},5000);setInterval(()=>{if(!$('#quietScreen').hidden)$('#quietClock').textContent=clock(new Date(),false)},1000)}
function setRegion(region){if(region)localStorage.setItem('nebo-region',region);else localStorage.removeItem('nebo-region');audio.prime(state.snapshot,region);renderSky();renderRadar();if(region&&!localStorage.getItem('nebo-audio-prompted'))$('#audioPrompt').showModal()}
function setupAudioSettings(){const ids={officialStart:'audioOfficialStart',officialEnd:'audioOfficialEnd',uav:'audioUav',missile:'audioMissile',kab:'audioKab',aviation:'audioAviation'};for(const[type,id]of Object.entries(ids))$('#'+id).onchange=e=>audio.save({[type]:e.target.checked});$('#audioEnabled').onchange=async e=>{if(e.target.checked){try{await audio.enable()}catch{audio.save({enabled:false});e.target.checked=false}}else audio.save({enabled:false})};$('#audioVolume').oninput=e=>{audio.save({volume:Number(e.target.value)/100});$('#audioVolumeValue').textContent=`${e.target.value}%`};$('#quietHoursEnabled').onchange=e=>audio.save({quietHoursEnabled:e.target.checked});$('#quietStart').onchange=e=>audio.save({quietStart:e.target.value});$('#quietEnd').onchange=e=>audio.save({quietEnd:e.target.value});$('#muteOfficialInQuiet').onchange=e=>audio.save({muteOfficialInQuiet:e.target.checked});$('#soundTests').innerHTML=AUDIO_TYPES.map(type=>`<button class="sound-test" data-sound="${type}">${esc(AUDIO_LABELS[type])}</button>`).join('');$('#soundTests').onclick=e=>{const button=e.target.closest('[data-sound]');if(button)audio.test(button.dataset.sound).catch(()=>{$('#testSoundState').hidden=false;$('#testSoundState').textContent='ТЕСТ ЗВУКУ · браузер заблокував відтворення'})};$('#enableAudio').onclick=async()=>{try{await audio.enable();localStorage.setItem('nebo-audio-prompted','enabled');$('#audioPrompt').close();renderAudioSettings()}catch{$('#audioPrompt p').textContent='Браузер не дозволив відтворення. Спробуйте ще раз у налаштуваннях.'}};$('#laterAudio').onclick=()=>{localStorage.setItem('nebo-audio-prompted','later');$('#audioPrompt').close()};renderAudioSettings()}
function renderAudioSettings(){const p=audio.prefs,map={audioOfficialStart:'officialStart',audioOfficialEnd:'officialEnd',audioUav:'uav',audioMissile:'missile',audioKab:'kab',audioAviation:'aviation'};$('#audioEnabled').checked=p.enabled;for(const[id,key]of Object.entries(map))$('#'+id).checked=p[key];$('#audioVolume').value=Math.round(p.volume*100);$('#audioVolumeValue').textContent=`${Math.round(p.volume*100)}%`;$('#quietHoursEnabled').checked=p.quietHoursEnabled;$('#quietStart').value=p.quietStart;$('#quietEnd').value=p.quietEnd;$('#muteOfficialInQuiet').checked=p.muteOfficialInQuiet}
function showView(id){$$('.view').forEach(v=>v.hidden=v.id!==id);$$('.nav-item').forEach(b=>{const active=b.dataset.nav===id;b.classList.toggle('active',active);active?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current')});if(id==='radarView'){applyRadarMode();setTimeout(()=>radarUI.map.invalidateSize(),50)}else{scopeUI.setActive(false);if(id==='mapView')setTimeout(()=>mapUI.map.invalidateSize(),50)}}
function locate(){if(!navigator.geolocation){toastLoc('Геолокація не підтримується цим браузером.');return}const b=$('#locateButton');b.disabled=true;toastLoc('Визначаємо положення…');navigator.geolocation.getCurrentPosition(p=>{b.disabled=false;applyPosition(p.coords);startWatch()},()=>{b.disabled=false;toastLoc('Доступ до геолокації не надано. Дозвольте доступ у налаштуваннях браузера.');b.title='Доступ до геолокації не надано'},{timeout:12000,maximumAge:10000,enableHighAccuracy:true})}
function toastLoc(t){const s=$('#placeSearchStatus');if(s)s.textContent=t}
function applyPosition(c){if(!c||!Number.isFinite(c.latitude)||!Number.isFinite(c.longitude))return;state.userPos={lat:c.latitude,lon:c.longitude,acc:Number.isFinite(c.accuracy)?c.accuracy:null,at:Date.now()};mapUI.setUserPos(state.userPos);if(centerOnNextPos){centerOnNextPos=false;mapUI.centerOnUser()}const f=state.geo?.features.find(x=>pointInFeature([c.latitude,c.longitude],x));if(f){const n=regionName(f);if(n!==localStorage.getItem('nebo-region'))setRegion(n)}toastLoc(`GPS: ${state.userPos.acc!=null?`±${Math.round(state.userPos.acc)} м`:''} · ${clock(new Date(),true)}`);renderAll()}
function startWatch(){if(!navigator.geolocation||state.watchId!=null)return;let last=0;try{state.watchId=navigator.geolocation.watchPosition(p=>{const now=Date.now();if(now-last<8000)return;const u=state.userPos;if(!u||distKm(u.lat,u.lon,p.coords.latitude,p.coords.longitude)*1000>300){last=now;applyPosition(p.coords)}},null,{timeout:20000,maximumAge:15000,enableHighAccuracy:false})}catch(e){}}
function countCats(events){const c={uav:0,missile:0,ballistic:0,kab:0,aviation:0,recon:0,other:0};events.forEach(e=>c[e.category]=(c[e.category]||0)+1);return c}function label(k){return META[k]?.label||'Інше'}function stat(n,v){return`<span class="live-stat"><b>${v}</b>${n}</span>`}function monitorCell(n,v){return`<div class="monitor-cell"><b>${v}</b><span>${n} · повідомлень</span></div>`}function field(n,v){return`<div class="detail-field"><span>${n}</span><b>${esc(v)}</b></div>`}function positionLabel(q){return q==='confirmed'?'підтверджена джерелом':q==='approx'?'приблизна':q==='source-position'?'позиція джерела':'якість не передана'}
function fresh(d){if(!d)return'час не передано';const s=Math.max(0,Math.round((Date.now()-new Date(d).getTime())/1000));if(s<60)return`${s} сек тому`;if(s<3600)return`${Math.floor(s/60)} хв тому`;return`${Math.floor(s/3600)} год тому`}function clock(d,short=false){if(!d)return'—';return new Intl.DateTimeFormat('uk-UA',{hour:'2-digit',minute:'2-digit',second:short?undefined:'2-digit'}).format(new Date(d))}function compass(h){return['Пн','ПнСх','Сх','ПдСх','Пд','ПдЗх','Зх','ПнЗх'][Math.round(h/45)%8]}function distKm(a,b,c,d){const r=6371,p=Math.PI/180,dLa=(c-a)*p,dLo=(d-b)*p,x=Math.sin(dLa/2)**2+Math.cos(a*p)*Math.cos(c*p)*Math.sin(dLo/2)**2;return 2*r*Math.asin(Math.sqrt(x))}function bearingDeg(a,b,c,d){const p=Math.PI/180,y=Math.sin((d-b)*p)*Math.cos(c*p),x=Math.cos(a*p)*Math.sin(c*p)-Math.sin(a*p)*Math.cos(c*p)*Math.cos((d-b)*p);return(Math.atan2(y,x)/p+360)%360}function fmtDist(km){return km<10?`${km.toFixed(1).replace('.',',')} км`:`${Math.round(km)} км`}function fmtEta(min){return min<1?'менше хвилини':min<60?`~${Math.round(min)} хв`:`~${Math.floor(min/60)} год ${Math.round(min%60)} хв`}function annotateDistances(){const u=state.userPos;for(const e of state.snapshot.events){e._distKm=null;e._closing=false;e._etaMin=null;e._lvl=threatLevel(e);if(!u||e.lat==null||e.lon==null)continue;const d=distKm(u.lat,u.lon,e.lat,e.lon);e._distKm=d;const h=Number(e.heading),s=Number(e.speed);if(Number.isFinite(h)&&Number.isFinite(s)&&s>0){const brg=bearingDeg(e.lat,e.lon,u.lat,u.lon);let diff=Math.abs(h-brg)%360;if(diff>180)diff=360-diff;if(diff<35){e._closing=true;e._etaMin=d/s*60}};e._lvl=threatLevel(e)}}function saveJSON(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}
function loadJSON(k,f){try{const v=JSON.parse(localStorage.getItem(k));return v==null?f:v}catch(e){return f}}
function flowEvents(){return state.onlyFresh?state.snapshot.events.filter(e=>!e.stale):state.snapshot.events}
function nearestEvent(){let best=null;for(const e of flowEvents())if(e._distKm!=null&&(!best||e._distKm<best._distKm))best=e;return best}function centerOf(f){const pts=[];walk(f.geometry.coordinates,pts);const b=pts.reduce((a,p)=>[Math.min(a[0],p[1]),Math.min(a[1],p[0]),Math.max(a[2],p[1]),Math.max(a[3],p[0])],[90,180,-90,-180]);return[(b[0]+b[2])/2,(b[1]+b[3])/2]}function walk(a,out){if(typeof a?.[0]==='number')out.push(a);else a?.forEach(x=>walk(x,out))}function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
setup();setupEnhancements({getSnapshot:()=>state.snapshot,onRegion:setRegion,onRender:renderSky});$('#openSources').onclick=()=>{$('#settingsDialog').close();showView('threatsView');setTimeout(()=>$('#sourceHealth').scrollIntoView({behavior:'smooth'}),80)};load();if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));
